/**
 * D-001 Stage-2 machine-readable envelope
 * DECLARED_STAGE2_CAPABILITY. measured = false. commissioned = false.
 * Numbers exist to exercise fit → ops → minutes → Q. They do not authorize live motion.
 */
const D001_STAGE2_ENVELOPE = {
  id: "D001-STAGE2-ENVELOPE-0.4",
  basis: "DECLARED_STAGE2_CAPABILITY",
  measured: false,
  commissioned: false,
  axes: {
    X: "along fence / workpiece feed",
    Y: "perpendicular to fence / across width",
    Z: "vertical tool engagement / depth",
    fenceY: 0,
    tableZ: 0
  },
  base: {
    lengthIn: 72,
    note: "Stage-2 fixture base geometry only. This is not a required stock length or project workpiece length."
  },
  stock: {
    maxWidthIn: 12.0,
    minWidthIn: 1.5,
    minThicknessIn: 0.75,
    maxThicknessSawIn: 3.5,
    maxThicknessMillIn: 1.5,
    maxParentLengthWithoutExternalSupportIn: 96,
    minControlledLengthIn: 24,
    externalSupport: "UNRESOLVED"
  },
  saw: {
    motion: "DOWNSTROKE",
    miter: {
      operation: "MITER_LIMITED",
      plane: "SINGLE_PLANE_FACE",
      minDeg: 0,
      maxDeg: 45,
      compound: false
    }
  },
  spot: {
    operation: "SPOT_ON_LOCATION",
    operationContract: "SPOT_ON_LOCATION/0.2",
    mode: "SPOT_ON_LOCATION",
    toolDefinitionId: "D001-SPOT-3_16-TOOL-0.2",
    toolDiameterIn: 0.1875,
    toolDiameterLabel: "3/16 in",
    fullDiameterPenetrationIn: 0.1875,
    depthReference: "ENTRY_SURFACE_ALONG_DRILL_AXIS",
    pointAngleDeg: null,
    pointAxialLengthIn: null,
    pointGeometryStatus: "UNRESOLVED",
    totalTipPenetrationIn: null,
    customerDepthProgrammingRequired: false,
    locationRule: "CENTERED_ON_PART",
    acrossWidthRule: "CENTERED_ON_WIDE_FACE",
    depthClaimed: true,
    note: "Bounded 3/16 in spot operation. Full-diameter penetration is 3/16 in below the entry surface. Total tip penetration remains unresolved until the selected tool point geometry is declared."
  },
  motion: {
    FEED_X_MAX_LOADED_IN_PER_MIN: 480,
    MILL_CUTTING_FEED_IN_PER_MIN: 48,
    Y_MILL_TRAVEL_MAX_IN: 14.0,
    note: "14 in is tool travel. 12 in is max stock width. Do not equate them."
  },
  stations: {
    "SAW-L": { xIn: 0, role: "infeed-end downstroke chop / single-plane miter 0–45 deg" },
    R1: { xIn: 24, role: "manipulating roller" },
    MILL_LONG: { xIn: 36, role: "longitudinal mill between R1 and R2" },
    R2: { xIn: 48, role: "manipulating roller" },
    "SAW-R": { xIn: 72, role: "outfeed-end downstroke square chop" },
    MILL_END: { xIn: -6, role: "end mill outside roller interference" }
  },
  exclusion: ["R1", "R2", "SAW-L", "SAW-R"],
  millLong: {
    maxProfileLengthIn: 60,
    maxDepthPerPassIn: 0.375,
    maxCutWidthIn: 1.0
  },
  millEnd: {
    reachFromEndIn: 8,
    maxDepthIn: 0.5
  },
  unresolvedNamed: [
    "third manipulating roller (patent 504 is three; Stage-2 fixture names two)",
    "radial-arm vs second chop as distinct saw types",
    "third router/drill on a vertical way",
    "selected 3/16 SPOT_ON_LOCATION tool point angle / axial point length",
    "generic DRILL diameter / depth / location beyond the declared 3/16 SPOT_ON_LOCATION operation",
    "unsupported overhang geometry",
    "whether a short part may run on one roller"
  ]
};

function millPassesForDepth(totalDepthIn) {
  if (!totalDepthIn || totalDepthIn <= 0) return 1;
  return Math.ceil(totalDepthIn / D001_STAGE2_ENVELOPE.millLong.maxDepthPerPassIn);
}

function finiteNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function envelopeCheck(item, req = {}) {
  const reasons = [];
  const unresolved = [];
  if (!item) return { status: "REFUSED", reasons: ["NO_OFFERING"], unresolved, envelope: D001_STAGE2_ENVELOPE.id };
  if (item.form === "sheet") {
    return { status: "REFUSED", reasons: ["SHEET_NOT_D001"], unresolved, envelope: D001_STAGE2_ENVELOPE.id };
  }
  if (item.form === "hardware") {
    return { status: "SOURCED", reasons: [], unresolved, envelope: D001_STAGE2_ENVELOPE.id };
  }

  const w = item.actualW;
  const t = item.actualT;
  const L = item.stockL_in;
  const e = D001_STAGE2_ENVELOPE.stock;
  const ops = req.requiredOps || [];

  if (w != null && w > e.maxWidthIn) reasons.push("STOCK_WIDTH_EXCEEDS_D001_STAGE2_ENVELOPE");
  if (w != null && w < e.minWidthIn) reasons.push("STOCK_WIDTH_BELOW_D001_STAGE2_ENVELOPE");
  if (L != null && L > e.maxParentLengthWithoutExternalSupportIn) {
    reasons.push("PARENT_LENGTH_REQUIRES_UNDECLARED_EXTERNAL_SUPPORT");
  }

  const needsMill = ops.some((op) =>
    ["MILL_LONGITUDINAL_PROFILE", "MILL_END_PROFILE", "DADO", "GROOVE", "RABBET"].includes(op)
  );
  const maxT = needsMill ? e.maxThicknessMillIn : e.maxThicknessSawIn;
  if (t != null && t > maxT) reasons.push("STOCK_THICKNESS_EXCEEDS_D001_STAGE2_ENVELOPE");
  if (t != null && t < e.minThicknessIn) reasons.push("STOCK_THICKNESS_BELOW_D001_STAGE2_ENVELOPE");

  if (req.keptLengthIn != null && req.keptLengthIn < e.minControlledLengthIn) {
    reasons.push("KEPT_LENGTH_BELOW_TWO_ROLLER_CONTROL");
  }
  if (req.millYIn != null && req.millYIn > D001_STAGE2_ENVELOPE.motion.Y_MILL_TRAVEL_MAX_IN) {
    reasons.push("MILL_Y_EXCEEDS_TOOL_TRAVEL");
  }

  if (ops.includes("MITER_LIMITED")) {
    const angle = finiteNumber(req.sawAngleDeg);
    if (angle == null) {
      unresolved.push("MITER_ANGLE_REQUIRED");
    } else if (
      angle < D001_STAGE2_ENVELOPE.saw.miter.minDeg ||
      angle > D001_STAGE2_ENVELOPE.saw.miter.maxDeg
    ) {
      reasons.push("MITER_ANGLE_OUTSIDE_D001_STAGE2_ENVELOPE");
    }
    if (req.cutPlane != null && req.cutPlane !== "miter-face") {
      reasons.push("MITER_PLANE_NOT_DECLARED");
    }
  }

  if (ops.includes("DRILL")) {
    unresolved.push("GENERIC_DRILL_ENVELOPE_NOT_DECLARED_BEYOND_SPOT");
  }

  const spot = req.spotDemand;
  if (spot && spot.required !== false) {
    if (spot.mode !== D001_STAGE2_ENVELOPE.spot.mode) {
      reasons.push("SPOT_MODE_NOT_DECLARED");
    }
    if (spot.locationRule !== D001_STAGE2_ENVELOPE.spot.locationRule) {
      reasons.push("SPOT_LOCATION_RULE_NOT_DECLARED");
    }
    if (spot.acrossWidthRule !== D001_STAGE2_ENVELOPE.spot.acrossWidthRule) {
      reasons.push("SPOT_ACROSS_WIDTH_RULE_NOT_DECLARED");
    }
    if (
      t != null &&
      D001_STAGE2_ENVELOPE.spot.fullDiameterPenetrationIn > t
    ) {
      reasons.push("SPOT_FULL_DIAMETER_DEPTH_EXCEEDS_STOCK_THICKNESS");
    }
    if (D001_STAGE2_ENVELOPE.spot.pointGeometryStatus !== "DECLARED") {
      unresolved.push("SPOT_TOOL_POINT_GEOMETRY_REQUIRED");
    }
    const along = finiteNumber(spot.locationAlongLengthIn);
    const spotReferenceLengthIn = finiteNumber(
      req.finishedPartLengthIn != null ? req.finishedPartLengthIn : req.keptLengthIn
    );
    if (along == null) {
      unresolved.push("SPOT_LOCATION_REQUIRED");
    } else if (
      along < 0 ||
      (spotReferenceLengthIn != null && along > spotReferenceLengthIn)
    ) {
      reasons.push("SPOT_LOCATION_OUTSIDE_WORKPIECE");
    }
  }

  const have = new Set(item.supportedOps || []);
  const missing = ops.filter((op) => !have.has(op));
  if (missing.length) reasons.push(`OP_NOT_ON_OFFERING:${missing.join(",")}`);

  const family = item.cellFamily || [];
  if (family.length && !family.includes("D-001")) reasons.push("CELL_FAMILY_NOT_D001");

  const status = reasons.length ? "REFUSED" : unresolved.length ? "UNRESOLVED" : "SUPPORTABLE";
  return {
    status,
    reasons,
    unresolved,
    envelope: D001_STAGE2_ENVELOPE.id,
    derived: {
      millPasses: millPassesForDepth(req.millDepthIn || 0),
      miter:
        ops.includes("MITER_LIMITED")
          ? {
              requestedDeg: finiteNumber(req.sawAngleDeg),
              minDeg: D001_STAGE2_ENVELOPE.saw.miter.minDeg,
              maxDeg: D001_STAGE2_ENVELOPE.saw.miter.maxDeg,
              motion: D001_STAGE2_ENVELOPE.saw.motion
            }
          : null,
      spot:
        spot && spot.required !== false
          ? {
              mode: D001_STAGE2_ENVELOPE.spot.mode,
              operationContract: D001_STAGE2_ENVELOPE.spot.operationContract,
              toolDefinitionId: D001_STAGE2_ENVELOPE.spot.toolDefinitionId,
              toolDiameterIn: D001_STAGE2_ENVELOPE.spot.toolDiameterIn,
              fullDiameterPenetrationIn: D001_STAGE2_ENVELOPE.spot.fullDiameterPenetrationIn,
              depthReference: D001_STAGE2_ENVELOPE.spot.depthReference,
              pointAngleDeg: D001_STAGE2_ENVELOPE.spot.pointAngleDeg,
              pointAxialLengthIn: D001_STAGE2_ENVELOPE.spot.pointAxialLengthIn,
              pointGeometryStatus: D001_STAGE2_ENVELOPE.spot.pointGeometryStatus,
              totalTipPenetrationIn: D001_STAGE2_ENVELOPE.spot.totalTipPenetrationIn,
              customerDepthProgrammingRequired: D001_STAGE2_ENVELOPE.spot.customerDepthProgrammingRequired,
              depthClaimed: true
            }
          : null
    }
  };
}


/**
 * Store Zero Stage-2 pricing engine
 * Budgetary estimate only. Not a commercial quote. Not a seller-of-record.
 *
 * sell = ROUND(list_reference * 1.05, 2)   DECLARED_FIXTURE rule SZ-MARK-ON-5
 * cycle minutes are CALCULATED / MODELED under CYCLE_MODEL
 */

const ENGINE = {
  id: "STB-STORE-ZERO-PRICE-1",
  version: "0.3.0",
  clock: "2026-09-10",
  documentKind: "BudgetaryEstimate"
};

/** Named Stage-2 cycle model. Not measured D-001 production data. */
const CYCLE_MODEL = {
  id: "STB-D001-CYCLE-MODEL-S2-0.1",
  basis: "CALCULATED",
  measured: false,
  commissioned: false,
  purpose: "deterministic modeled economics now; measured machine economics later"
};

const MARK_ON = 0.05;

function sellingPrice(list) {
  return Math.round(list * (1 + MARK_ON) * 100) / 100;
}

const RECOVERY = {
  setupCharge: 35,
  machineHourRate: 100
};

const TOOLING = {
  saw: {
    diameterIn: 10,
    rpm: 3450,
    teeth: 60,
    chipLoadCrossSoft: 0.003,
    finishFactor: 0.5,
    deployMin: 0.08,
    retractMin: 0.08
  },
  rapidInPerMin: D001_STAGE2_ENVELOPE.motion.FEED_X_MAX_LOADED_IN_PER_MIN,
  accelMin: 0.05,
  loadSeatMin: 0.6,
  releaseLabelMin: 0.4,
  jobSetupMin: 8,
  drill: { rpm: 3000, ipr: 0.008 },
  spot: {
    diameterIn: 0.1875,
    fullDiameterPenetrationIn: 0.1875,
    depthReference: "ENTRY_SURFACE_ALONG_DRILL_AXIS",
    pointGeometryStatus: D001_STAGE2_ENVELOPE.spot.pointGeometryStatus,
    pointAngleDeg: D001_STAGE2_ENVELOPE.spot.pointAngleDeg,
    pointAxialLengthIn: D001_STAGE2_ENVELOPE.spot.pointAxialLengthIn,
    legacyFixedCycleMin: 0.16,
    legacyCycleBasis: "DECLARED_FIXTURE_DEPTH_UNDEFINED",
    applicabilityStatus: "UNRESOLVED_FOR_DEPTH_DEFINED_SPOT",
    note: "The prior fixed 0.16 min spot cycle belongs to the depth-undefined spot model. Applicability to the new 3/16 full-diameter penetration is unresolved until tool-point geometry and depth-cycle basis are declared."
  }
};

const MILL = {
  longDeploy: 0.1,
  longFeedInPerMin: D001_STAGE2_ENVELOPE.motion.MILL_CUTTING_FEED_IN_PER_MIN,
  longRepass: 0.08,
  longRetract: 0.1,
  endFeatureMin: 0.35
};

function round(n, p = 2) {
  const m = 10 ** p;
  return Math.round(n * m) / m;
}

function sfm(saw = TOOLING.saw) {
  return (Math.PI * saw.diameterIn * saw.rpm) / 12;
}

function feedFpm(saw = TOOLING.saw) {
  return ((saw.chipLoadCrossSoft * saw.teeth * saw.rpm) / 12) * saw.finishFactor;
}

function sawCycleMin(widthIn, saw = TOOLING.saw) {
  return saw.deployMin + widthIn / (feedFpm(saw) * 12) + saw.retractMin;
}

function drillCycleMin(depthIn, drill = TOOLING.drill) {
  return TOOLING.saw.deployMin + depthIn / (drill.ipr * drill.rpm) + TOOLING.saw.retractMin;
}

function spotCycleMin() {
  if (TOOLING.spot.applicabilityStatus !== "APPLICABLE") {
    throw new Error("SPOT_CYCLE_TIME_APPLICABILITY_UNRESOLVED");
  }
  return TOOLING.spot.legacyFixedCycleMin;
}

function spotEconomicsAssessment() {
  return {
    status: TOOLING.spot.applicabilityStatus,
    legacyFixedCycleMin: TOOLING.spot.legacyFixedCycleMin,
    legacyCycleBasis: TOOLING.spot.legacyCycleBasis,
    fullDiameterPenetrationIn: TOOLING.spot.fullDiameterPenetrationIn,
    pointGeometryStatus: TOOLING.spot.pointGeometryStatus,
    note: TOOLING.spot.note
  };
}

function indexMin(keptLengthIn) {
  return TOOLING.accelMin + Math.abs(keptLengthIn) / TOOLING.rapidInPerMin;
}

function millLongMin(profileLengthIn = 0, passes = 1) {
  if (!profileLengthIn) return 0;
  const n = Math.max(1, passes);
  return MILL.longDeploy + profileLengthIn / MILL.longFeedInPerMin + (n - 1) * MILL.longRepass + MILL.longRetract;
}

function millEndMin(count = 0) {
  return count * MILL.endFeatureMin;
}

function cycleOneStick({
  keptLengthIn,
  widthIn,
  holes = 0,
  spots = 0,
  depthIn = 0.75,
  sawCuts = 2,
  sawTraverseIn = null,
  millLongIn = 0,
  millEnds = 0,
  millDepthIn = 0,
  passes = 1
}) {
  const cutCount = Math.max(0, Number(sawCuts) || 0);
  const traverse = Number.isFinite(Number(sawTraverseIn)) && Number(sawTraverseIn) > 0
    ? Number(sawTraverseIn)
    : widthIn;
  const saw = sawCycleMin(traverse);
  const millPasses = millDepthIn ? millPassesForDepth(millDepthIn) : passes;
  const total =
    TOOLING.loadSeatMin +
    cutCount * saw +
    indexMin(keptLengthIn) +
    holes * drillCycleMin(depthIn) +
    (spots > 0 ? spots * spotCycleMin() : 0) +
    millLongMin(millLongIn, millPasses) +
    millEndMin(millEnds) +
    TOOLING.releaseLabelMin;
  return round(total, 3);
}

function findOffering(catalog, storeSku) {
  return catalog.offerings.find((o) => o.storeSku === storeSku) || null;
}

function extendLine(catalog, storeSku, qty) {
  const item = findOffering(catalog, storeSku);
  if (!item || item.sellingPrice == null) {
    return { storeSku, qty, status: "INCOMPLETE", reason: "MISSING_PRICE" };
  }
  return {
    storeSku,
    description: item.description,
    qty,
    list_reference: item.list_reference,
    listReferenceBasis: item.listReferenceBasis,
    mark_on: MARK_ON,
    selling_price: item.sellingPrice,
    extension: round(item.sellingPrice * qty, 2),
    sellingPriceBasis: "CALCULATED",
    observationId: item.observationId || null
  };
}

function estimateJob(catalog, { title, classId, pieces, hardwareSku = null }) {
  const lines = pieces.map((p) => extendLine(catalog, p.storeSku, p.qty));
  if (lines.some((l) => l.status === "INCOMPLETE")) {
    return { status: "UNRESOLVED", reason: "MISSING_PRICE", title };
  }
  const cycleMin =
    TOOLING.jobSetupMin +
    pieces.reduce((s, p) => s + cycleOneStick(p) * p.qty, 0);
  const hours = cycleMin / 60;
  const material = round(lines.reduce((s, l) => s + l.extension, 0), 2);
  let hardware = 0;
  let hardwareLine = null;
  if (hardwareSku) {
    hardwareLine = extendLine(catalog, hardwareSku, 1);
    if (hardwareLine.status === "INCOMPLETE") {
      return { status: "UNRESOLVED", reason: "MISSING_HARDWARE_PRICE", title };
    }
    hardware = hardwareLine.extension;
  }
  const cell = round(RECOVERY.setupCharge + RECOVERY.machineHourRate * hours, 2);
  const Q = round(material + cell + hardware, 2);
  return {
    status: "BUDGETARY_ESTIMATE",
    title,
    classId,
    documentKind: ENGINE.documentKind,
    engine: ENGINE,
    material_lines: lines,
    hardware_line: hardwareLine,
    cycle: {
      model: CYCLE_MODEL.id,
      basis: CYCLE_MODEL.basis,
      measured: false,
      T_job_min: round(cycleMin, 3),
      T_job_hr: round(hours, 4),
      SFM: round(sfm(), 0),
      feed_fpm: round(feedFpm(), 2)
    },
    totals: {
      material,
      cell_recovery: cell,
      hardware,
      Q,
      Q_basis: "CALCULATED",
      note: "Budgetary estimate. Not a commercial quote."
    },
    not_claimed: [
      "commercial quote",
      "seller-of-record",
      "physical fabrication",
      "live motion",
      "physical stock count"
    ]
  };
}

function estimateBoardSequence(catalog, {
  title,
  classId = "user_defined_board",
  storeSku,
  qty = 1,
  definedWorkpieceLengthIn,
  sawCuts,
  sawAngleDeg = 0,
  drillCycles = 0,
  spotCycles = 0,
  drillReferenceDepthIn = 0.75
}) {
  const item = findOffering(catalog, storeSku);
  if (!item || item.form !== "board" || item.actualW == null) {
    return { status: "UNRESOLVED", reason: "BOARD_OFFERING_REQUIRED", title };
  }
  const angle = Math.max(0, Math.min(89, Number(sawAngleDeg) || 0));
  const radians = angle * Math.PI / 180;
  const sawTraverseIn = angle > 0
    ? item.actualW / Math.cos(radians)
    : item.actualW;
  const spotCount = Math.max(0, Number(spotCycles) || 0);
  const spotAssessment = spotEconomicsAssessment();
  const spotEconomicsResolved =
    spotCount === 0 || spotAssessment.status === "APPLICABLE";

  const estimate = estimateJob(catalog, {
    title,
    classId,
    pieces: [{
      storeSku,
      qty,
      keptLengthIn: definedWorkpieceLengthIn,
      widthIn: item.actualW,
      sawCuts,
      sawTraverseIn,
      holes: drillCycles,
      spots: spotEconomicsResolved ? spotCount : 0,
      depthIn: drillReferenceDepthIn
    }]
  });

  if (spotCount > 0 && !spotEconomicsResolved) {
    return {
      ...estimate,
      status: "PARTIAL_BUDGETARY_ESTIMATE",
      unresolved: ["SPOT_CYCLE_TIME_APPLICABILITY_UNRESOLVED"],
      operationEconomics: {
        spot: {
          requestedCycles: spotCount,
          status: spotAssessment.status,
          legacyFixedCycleMin: spotAssessment.legacyFixedCycleMin,
          legacyCycleBasis: spotAssessment.legacyCycleBasis,
          excludedFromResolvedSubtotal: true
        }
      },
      cycle: {
        ...estimate.cycle,
        excludedSpotCycles: spotCount,
        spotCycleStatus: spotAssessment.status
      },
      totals: {
        ...estimate.totals,
        Q_basis: "PARTIAL_CALCULATED",
        note: "Partial budgetary subtotal. Excludes unresolved depth-defined spot-cycle time."
      }
    };
  }

  return estimate;
}


function estimateBoardPlan(catalog, {
  title,
  classId = "user_defined_board",
  plan,
  spotCycles = 0
}) {
  const selected = plan?.selected;
  const item = selected ? findOffering(catalog, selected.storeSku) : null;
  if (!item || item.form !== "board" || item.actualW == null || !Number.isInteger(selected.parentCount) || selected.parentCount < 1) {
    return { status: "UNRESOLVED", reason: "SELECTED_BOARD_PLAN_REQUIRED", title };
  }

  const materialLine = extendLine(catalog, selected.storeSku, selected.parentCount);
  if (materialLine.status === "INCOMPLETE") {
    return { status: "UNRESOLVED", reason: "MISSING_PRICE", title };
  }

  const angle = Number(plan.finishedPart?.angleDeg ?? 0);
  const radians = angle * Math.PI / 180;
  const miterTraverseIn = angle > 0 ? item.actualW / Math.cos(radians) : item.actualW;
  const productionSawCuts = Number(plan.accounting?.productionSawCuts ?? 0);
  const preparationSawCuts = Number(plan.accounting?.preparationSawCuts ?? 0);
  const producedParts = Number(plan.finishedPart?.quantity ?? 0);
  const finishedLengthIn = Number(plan.finishedPart?.lengthIn ?? 0);

  const cycleMin =
    TOOLING.jobSetupMin +
    selected.parentCount * (TOOLING.loadSeatMin + TOOLING.releaseLabelMin) +
    productionSawCuts * sawCycleMin(miterTraverseIn) +
    preparationSawCuts * sawCycleMin(item.actualW) +
    producedParts * indexMin(finishedLengthIn);

  const spotCount = Math.max(0, Number(spotCycles) || 0);
  const spotAssessment = spotEconomicsAssessment();
  const spotEconomicsResolved = spotCount === 0 || spotAssessment.status === "APPLICABLE";
  const resolvedCycleMin = cycleMin + (spotEconomicsResolved && spotCount > 0 ? spotCount * spotCycleMin() : 0);
  const hours = resolvedCycleMin / 60;
  const material = materialLine.extension;
  const cell = round(RECOVERY.setupCharge + RECOVERY.machineHourRate * hours, 2);
  const Q = round(material + cell, 2);

  const estimate = {
    status: "BUDGETARY_ESTIMATE",
    title,
    classId,
    documentKind: ENGINE.documentKind,
    engine: ENGINE,
    material_lines: [materialLine],
    hardware_line: null,
    planIdentity: plan.planId ?? null,
    operationAccounting: {
      parentCount: selected.parentCount,
      productionSawCuts,
      preparationSawCuts,
      totalModeledSawCuts: productionSawCuts + preparationSawCuts,
      producedParts,
      spotCyclesRequested: spotCount,
      preparation: Array.isArray(plan.preparation) ? plan.preparation : []
    },
    cycle: {
      model: CYCLE_MODEL.id,
      basis: CYCLE_MODEL.basis,
      measured: false,
      T_job_min: round(resolvedCycleMin, 3),
      T_job_hr: round(hours, 4),
      SFM: round(sfm(), 0),
      feed_fpm: round(feedFpm(), 2)
    },
    totals: {
      material,
      cell_recovery: cell,
      hardware: 0,
      Q,
      Q_basis: "CALCULATED",
      note: "Budgetary estimate. Not a commercial quote."
    },
    not_claimed: [
      "commercial quote",
      "seller-of-record",
      "physical fabrication",
      "live motion",
      "physical stock count"
    ]
  };

  if (spotCount > 0 && !spotEconomicsResolved) {
    return {
      ...estimate,
      status: "PARTIAL_BUDGETARY_ESTIMATE",
      unresolved: ["SPOT_CYCLE_TIME_APPLICABILITY_UNRESOLVED"],
      operationEconomics: {
        spot: {
          requestedCycles: spotCount,
          status: spotAssessment.status,
          legacyFixedCycleMin: spotAssessment.legacyFixedCycleMin,
          legacyCycleBasis: spotAssessment.legacyCycleBasis,
          excludedFromResolvedSubtotal: true
        }
      },
      cycle: {
        ...estimate.cycle,
        excludedSpotCycles: spotCount,
        spotCycleStatus: spotAssessment.status
      },
      totals: {
        ...estimate.totals,
        Q_basis: "PARTIAL_CALCULATED",
        note: "Partial budgetary subtotal. Excludes unresolved depth-defined spot-cycle time."
      }
    };
  }

  return estimate;
}

